const vis = e => e.getClientRects().length > 0;
const sleep = ms => new Promise(r => setTimeout(r, ms));
const names = ['Player','Snaps','Ball Skills','Tackle Breaking','Elusiveness','Play Speed','Deep Speed','Burst','CoD','Decel','Run Blocking'];
const col = name => { const h = [...document.querySelectorAll('*')].find(e => vis(e) && e.children.length === 0 && e.textContent.trim() === name); if (!h) return []; let c = h; while (c.parentElement && c.parentElement.innerText.split('\n').length < 5) c = c.parentElement; return c.parentElement ? c.parentElement.innerText.split('\n').map(s => s.trim()).filter(Boolean).slice(1) : []; };
const box = [...document.querySelectorAll('*')].find(e => vis(e) && e.scrollHeight > e.clientHeight + 50 && String(e.className).includes('leaderboard'));
const tally = {}; names.slice(2).forEach(n => tally[n] = {values: 0, blank: 0});
const samples = [];
const seen = new Set();
for (const frac of [0, 0.33, 0.66, 1]) {
  box.scrollTop = Math.round((box.scrollHeight - box.clientHeight) * frac);
  await sleep(1500);
  const cols = Object.fromEntries(names.map(n => [n, col(n)]));
  const n = cols['Player'].length;
  for (let i = 0; i < n; i++) {
    const key = cols['Player'][i];
    if (seen.has(key)) continue;
    seen.add(key);
    names.slice(2).forEach(t => { const v = cols[t][i]; if (v === undefined) return; if (v === '---' || v === '') tally[t].blank++; else tally[t].values++; });
  }
  samples.push({frac, rows: n, first: cols['Player'][0], snaps: cols['Snaps'].slice(0, 5), sample: names.slice(2).map(t => t + '=' + (cols[t][0] ?? '?')).join(' ')});
}
box.scrollTop = 0;
({rowsSampled: seen.size, tally, samples})

