unknown = Counter()
for code, n in codes.items():
    if code in GROUP_OF_CODE:
        groups[GROUP_OF_CODE[code]] += n
    else:
        unknown[code] += n
total = sum(codes.values())
tab = "advanced-stats" if "Player Impact" in header else "player-traits"
if not groups:
    group = "?" + ",".join(unknown) if unknown else "?EMPTY"
else:
