# (for example 10 "ST" rows in a 1,980-row WR Advanced Stats export).
mixed = len(groups) > 1 or sum(unknown.values()) > 0.05 * total
return {"tab": tab, "group": group, "rows": total, "codes": dict(codes),
        "unknown": dict(unknown), "mixed": mixed}

